arduino.globals:
const int clkPin_${COMP_SUFFIX} = 2;
const int dtPin_${COMP_SUFFIX} = 3;
const int swPin_${COMP_SUFFIX} = 4;
int lastClk_${COMP_SUFFIX} = HIGH;

arduino.setup:
pinMode(clkPin_${COMP_SUFFIX}, INPUT_PULLUP);
pinMode(dtPin_${COMP_SUFFIX}, INPUT_PULLUP);
pinMode(swPin_${COMP_SUFFIX}, INPUT_PULLUP);
Serial.begin(9600);

arduino.loop:
int clk_${COMP_SUFFIX} = digitalRead(clkPin_${COMP_SUFFIX});
if(clk_${COMP_SUFFIX} != lastClk_${COMP_SUFFIX}) {
  if(digitalRead(dtPin_${COMP_SUFFIX}) != clk_${COMP_SUFFIX}) Serial.println("Rotated CW");
  else Serial.println("Rotated CCW");
}
lastClk_${COMP_SUFFIX} = clk_${COMP_SUFFIX};
if(digitalRead(swPin_${COMP_SUFFIX}) == LOW) Serial.println("Button Pressed");
delay(1);
